public class AutoTestNode{public static void main(String[]a)throws Exception{Path root=Paths.get(a[0]);int role=Integer.parseInt(a[1]),discovery=Integer.parseInt(a[3]);RoomServer server=new RoomServer(n->Files.readAllBytes(n.equals("bridge.swf")&&a.length>4&&!a[4].isEmpty()?Paths.get(a[4]):root.resolve(n)),role==1);List<InetAddress> probes=new ArrayList<>();if(role==AutoPairing.AUTO){probes.add(InetAddress.getByName("127.0.0.2"));probes.add(InetAddress.getByName("127.0.0.3"));}else probes.add(InetAddress.getByName("127.0.0.1"));AutoPairing pairing=new AutoPairing(server,role,a[2],discovery,probes,a.length>5?InetAddress.getByName(a[5]):null);System.out.println("PORT="+server.port());Runtime.getRuntime().addShutdownHook(new Thread(()->{pairing.close();server.close();}));Thread commands=new Thread(()->{Scanner in=new Scanner(System.in);while(in.hasNextLine()){String line=in.nextLine();if(line.equals("RESET"))pairing.reset();if(line.equals("ACTIVE0"))pairing.active(false);if(line.equals("ACTIVE1"))pairing.active(true);}},"native-test-commands");commands.setDaemon(true);commands.start();while(true){System.out.println("SESSION="+pairing.status());Thread.sleep(250);}}}
